    scanf("%s", s);

    for (long long i = 0; i < n; i++) {
        if (s[i] == 'R') {
            z += g * b;
            r++;
        }
        if (s[i] == 'G') {
            z += r * b;
            g++;
        }
        if (s[i] == 'B') {
            z += r * g;
            b++;
        }
    }

    // Optimize the nested loop by reducing the number of checks
    for (long long o = 3; o <= n; o += 2) {
        for (long long i = o - 1; i < n; i++) {
            if (s[i] != s[i - o + 1] && s[i - o + 1] != s[i - o / 2]) {
                if (s[i - o / 2] != s[i]) {
                    z--;
                }
            }
        }
    }

    printf("%lld\n", z);
    return 0;
}

